<template><view class="page"><view class="eyebrow">学习专题</view><view class="page-title">先建框架，再记细节</view><view class="section-head"><view class="section-title">全部专题</view><view class="section-meta">按学习顺序</view></view><view v-if="loading" class="card state-card">正在加载专题…</view><view v-else-if="!items.length" class="card state-card">暂无专题，稍后再来看看。</view><view v-for="item in items" :key="item.title" class="card row"><view class="step">{{ item.no }}</view><view><view class="card-title">{{ item.title }}</view><view class="card-desc">{{ item.desc }}</view></view></view></view></template><script setup lang="ts">import { ref } from 'vue'; import { useDidShow } from '@tarojs/taro'; import { api, type TopicItem } from '@/api'; const items=ref<TopicItem[]>([]); const loading=ref(true); async function load(){const response=await api.getTopics();if(response.code===0&&response.data)items.value=response.data.items;loading.value=false} useDidShow(()=>void load())</script>
